arguments.command:
cd /tmp/sv-2342260498d64b67a7604fc0657f6d06 && \
aarch64-linux-gnu-objdump -T libmonosgen-2.0.so | awk '$4 == ".text"' | sort -k1 | awk '
{
  addr = strtonum("0x" $1)
  name = $NF
  addrs[NR] = addr
  names[NR] = name
  count = NR
}
END {
  targets[1] = strtonum("0x222098")
  targets[2] = strtonum("0x222234")
  targets[3] = strtonum("0x19bac0")
  targets[4] = strtonum("0x19bc14")
  for (t = 1; t <= 4; t++) {
    best = ""
    bestaddr = 0
    for (i = 1; i <= count; i++) {
      if (addrs[i] <= targets[t] && addrs[i] > bestaddr) {
        bestaddr = addrs[i]
        best = names[i]
      }
    }
    printf "0x%x -> %s+0x%x\n", targets[t], best, targets[t] - bestaddr
  }
}' 2>/dev/null

